 		Expect(match).To(BeTrue())
 		Expect(backStr).To(Equal([]string{"PodmanSession", "Podman Session"}))

 		match, backStr = session.GrepString("I am not here")
 		Expect(match).To(Not(BeTrue()))
 		Expect(backStr).To(BeNil())

 	})

